import sys

def solve():
    # Read N
    try:
        line = sys.stdin.read().split()
    except Exception:
        return

    if not line:
        return

    N = int(line[0])
    P = []
    for i in range(1, N + 1):
        P.append(int(line[i]))

    # Initialize ranks
    ranks = [0] * (N + 1)  # 1-based indexing
    r = 1  # Current rank counter

    # Process each person
    for i in range(1, N + 1):
        if ranks[i] == 0:
            # Person i has undetermined rank
            max_score = max(P[i:])  # Maximum score among undetermined people
            k = sum(1 for p in P[i:] if p == max_score)
            ranks[i] = r
            r += k
        else:
            ranks[i] = r

    # Print ranks
    for i in range(1, N + 1):
        print(ranks[i])

if __name__ == "__main__":
    solve()
